#!/usr/bin/env python3
# ===========================================================================
#  batch_run.py -> 2단계 슬래브 빌드 패치
#  실행:  cd ~/mfpvector && python3 patch_build.py
#
#  안전장치
#   - code/batch_run.py.bak 으로 원본 백업 (이미 있으면 덮어쓰지 않음)
#   - 앵커를 못 찾으면 아무것도 건드리지 않고 중단
#   - 패치 후 py_compile 실패 시 백업에서 자동 복구
#   - 되돌리기:  cp code/batch_run.py.bak code/batch_run.py
# ===========================================================================
import os, shutil, py_compile, sys, base64

P   = "code/batch_run.py"
BAK = "code/batch_run.py.bak"

NEW = base64.b64decode("").decode("utf-8")

if not os.path.exists(P):
    sys.exit("중단: " + P + " 가 없습니다. ~/mfpvector 에서 실행하십시오.")

src = open(P, encoding="utf-8").read()

if "SLAB_BOXZ" in src:
    sys.exit("이미 패치돼 있습니다.\n먼저 되돌리십시오:  cp code/batch_run.py.bak code/batch_run.py")

a = src.find("\ndef build(poly, pfas, wd):")
if a < 0:
    sys.exit("중단: build() 정의를 찾지 못했습니다. 파일을 건드리지 않았습니다.")
a += 1
b = src.find("\ndef ", a + 1)
if b < 0:
    sys.exit("중단: build() 의 끝을 찾지 못했습니다. 파일을 건드리지 않았습니다.")
b += 1
old = src[a:b]
for token in ("packmol", "editconf", "solvate", "npt.mdp", "index.ndx"):
    if token not in old:
        sys.exit("중단: build() 안에 '" + token + "' 가 없습니다. 예상과 다른 파일입니다.")
print("기존 build() 확인:", old.count("\n"), "줄")

if os.path.exists(BAK):
    print("백업이 이미 있습니다:", BAK, "(덮어쓰지 않음)")
else:
    shutil.copy2(P, BAK); print("백업 생성:", BAK)

headlines = src[:a].splitlines(True)
kept = [l for l in headlines if not l.startswith("NPOLY_BY=")]
if len(kept) != len(headlines):
    print("이전 패치의 NPOLY_BY 줄 제거")
head = "".join(kept)

open(P, "w", encoding="utf-8").write(head + NEW + src[b:])

try:
    py_compile.compile(P, doraise=True)
except Exception as ex:
    shutil.copy2(BAK, P)
    sys.exit("문법 오류 발생 -> 원본을 복구했습니다:\n" + str(ex))

print("패치 완료 · 문법 검증 통과")
print()
for poly, n, h, r in (("PE",65,17.7,0.855),("PVDF",54,14.8,1.68),
                      ("ECTFE",42,16.2,1.55),("PTFE",42,15.2,1.98)):
    print("   %-6s 사슬 %2d개  초기 z %5.1f nm  비정질 기준 %.3f g/cm3" % (poly,n,h,r))
print()
print("압축: 1ns@300K/200bar -> 2ns@500K -> 3ns@300K -> 1ns 수렴확인")
print("index.ndx: [ System ] + [ POL ] + [ PFA ]  (rerun grompp 대응)")
print()
print("다음 단계는 대화창의 안내를 따르십시오.")
